<?php session_start();if(empty($_SESSION['logged_in'])){header('Location: login.php');exit;}if(!isset($_SESSION['employees']))$_SESSION['employees']=[['id'=>1,'name'=>'Ayesha Khan','email'=>'ayesha@example.com','department'=>'IT'],['id'=>2,'name'=>'Ahmed Ali','email'=>'ahmed@example.com','department'=>'HR']];$list=$_SESSION['employees'];$d=$_GET['department']??'';if($d)$list=array_values(array_filter($list,fn($x)=>$x['department']===$d));function h($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employees</title><link rel="stylesheet" href="assets/style.css"></head><body><main><div class="head"><h1>Employee Management</h1><a href="logout.php">Logout</a></div><?php if(!empty($_SESSION['flash'])){echo '<p class="success">'.h($_SESSION['flash']).'</p>';unset($_SESSION['flash']);} ?><p><a class="btn" href="create.php">Add employee</a></p><form method="get"><label>Department<select name="department"><option value="">All</option><?php foreach(['IT','HR','Finance','Sales'] as $v)echo '<option '.($d===$v?'selected':'').'>'.$v.'</option>';?></select></label><button>Filter</button><a href="index.php">Reset</a></form><table><tr><th>Name</th><th>Email</th><th>Department</th><th>Details</th></tr><?php foreach($list as $x):?><tr><td><?=h($x['name'])?></td><td><?=h($x['email'])?></td><td><?=h($x['department'])?></td><td><a href="view.php?id=<?=$x['id']?>">View</a></td></tr><?php endforeach;?></table><p class="note">Demo employee data is stored in the PHP session, not MySQL.</p></main></body></html>